int Depth(BiTree T) {//计算二叉树T的深度
if(T==NULL)return 0;
else
{
m=Depth(T->1child); n=Depth(T->rchild);
if(m>n)return(m+1);
//如果是空树，深度为0,递归结束
//递归计算左子树的深度记为m
//递归计算右子树的深度记为n
else return(n+1);
}
